mapper.insert:
INSERT INTO user_reminders (
    user_id, pet_id, title, reminder_type, remind_at, note, status
) VALUES (
    #{userId}, #{petId}, #{title}, #{reminderType}, #{remindAt}, #{note}, 'active'
)

mapper.select:
SELECT id, user_id, pet_id, title, reminder_type, remind_at, note, status, created_at, updated_at FROM user_reminders
WHERE user_id = #{userId}
ORDER BY remind_at IS NULL, remind_at ASC

SELECT id, user_id, pet_id, title, reminder_type, remind_at, note, status, created_at, updated_at FROM user_reminders
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
UPDATE user_reminders
SET pet_id = #{petId},
    title = #{title},
    remind_at = #{remindAt},
    note = #{note}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'active'

UPDATE user_reminders
SET status = 'completed'
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('active', 'notified')

mapper.delete:
DELETE FROM user_reminders
WHERE id = #{id}
  AND user_id = #{userId}
